import{_ as e,c as a,o as n,ah as l}from"./chunks/framework._fWrWIYU.js";const b=JSON.parse('{"title":"julenum/integrate","description":"","frontmatter":{},"headers":[],"relativePath":"api/integrate.md","filePath":"api/integrate.md"}'),o={name:"api/integrate.md"};function r(t,s,i,p,c,d){return n(),a("div",null,s[0]||(s[0]=[l('<h1 id="julenum-integrate" tabindex="-1">julenum/integrate <a class="header-anchor" href="#julenum-integrate" aria-label="Permalink to “julenum/integrate”">​</a></h1><p>Package to compute an integral given a specific list of evaluations.</p><div><h2 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to “Index”">​</a></h2><p><a href="#gaussian">fn Gaussian[T: integer | float](x: []T, f: []T): T</a><br><a href="#romberg">fn Romberg[T: integer | float](f: []T, dx: T): T</a><br><a href="#simpsons">fn Simpsons[T: integer | float](x: []T, f: []T): T</a><br><a href="#trapezoidal">fn Trapezoidal[T: integer | float](x: []T, f: []T): T</a></p><h2 id="gaussian" tabindex="-1">Gaussian <a class="header-anchor" href="#gaussian" aria-label="Permalink to “Gaussian”">​</a></h2><div class="language-jule line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jule</span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#F286C4;">fn</span><span style="color:#F6F6F4;"> </span><span style="color:#97E1F1;">Gaussian</span><span style="color:#F6F6F4;">[T</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> integer </span><span style="color:#F286C4;">|</span><span style="color:#F6F6F4;"> float](x</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> []T, f</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> []T)</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> T</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Returns an approximate value of the integral</p><p>\\int_a^b f(x) dx</p><p>computed using the 3-point Composite Gauss-Legendre Quadrature rule.</p><p>The slice x represents the segment boundaries defining subintervals [x[i], x[i+1]]. The slice f contains the function samples evaluated at 3 Gauss nodes within each subinterval:</p><p>For subinterval i, the 3 nodes in physical space are: x_i,0 = mid - half * sqrt(3/5) x_i,1 = mid x_i,2 = mid + half * sqrt(3/5) where mid = (x[i+1] + x[i])/2 and half = (x[i+1] - x[i])/2.</p><p>Thus, len(f) must be equal to 3 * (len(x) - 1). The slice x must be sorted in strictly increasing order and len(x) &gt;= 2.</p><p>Computations are performed using 64-bit floating-point precision. The result is returned as type T, which may cause rounding errors or loss of precision. To preserve exact results, use 64-bit floating-point type.</p><h2 id="romberg" tabindex="-1">Romberg <a class="header-anchor" href="#romberg" aria-label="Permalink to “Romberg”">​</a></h2><div class="language-jule line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jule</span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#F286C4;">fn</span><span style="color:#F6F6F4;"> </span><span style="color:#97E1F1;">Romberg</span><span style="color:#F6F6F4;">[T</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> integer </span><span style="color:#F286C4;">|</span><span style="color:#F6F6F4;"> float](f</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> []T, dx</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> T)</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> T</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Returns an approximate value of the integral</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#f6f6f4;">\\int_a^b f(x)dx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>computed using the Romberg&#39;s method. The function f is given as a slice of equally-spaced samples, that is,</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#f6f6f4;">f[i] = f(a + i*dx)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>and dx is the spacing between the samples.</p><p>The length of f must be 2^k + 1, where k is a positive integer, and dx must be positive.</p><p>See <a href="https://en" target="_blank" rel="noreferrer">https://en</a>.wikipedia.org/wiki/Romberg%27s_method for a description of the algorithm.</p><p>Computations are performed using 64-bit floating-point precision. The result is returned as type T, which may cause rounding errors or loss of precision. To preserve exact results, use 64-bit floating-point type.</p><h2 id="simpsons" tabindex="-1">Simpsons <a class="header-anchor" href="#simpsons" aria-label="Permalink to “Simpsons”">​</a></h2><div class="language-jule line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jule</span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#F286C4;">fn</span><span style="color:#F6F6F4;"> </span><span style="color:#97E1F1;">Simpsons</span><span style="color:#F6F6F4;">[T</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> integer </span><span style="color:#F286C4;">|</span><span style="color:#F6F6F4;"> float](x</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> []T, f</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> []T)</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> T</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Returns an approximate value of the integral</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#f6f6f4;">\\int_a^b f(x)dx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>computed using the Simpsons&#39;s method. The function f is given as a slice of samples evaluated at locations in x, that is,</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#f6f6f4;">f[i] = f(x[i]), x[0] = a, x[len(x)-1] = b</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The slice x must be sorted in strictly increasing order. x and f must be of equal length and the length must be at least 3.</p><p>See <a href="https://en" target="_blank" rel="noreferrer">https://en</a>.wikipedia.org/wiki/Simpson%27s_rule#Composite_Simpson&#39;s_rule_for_irregularly_spaced_data for more information.</p><p>Computations are performed using 64-bit floating-point precision. The result is returned as type T, which may cause rounding errors or loss of precision. To preserve exact results, use 64-bit floating-point type.</p><h2 id="trapezoidal" tabindex="-1">Trapezoidal <a class="header-anchor" href="#trapezoidal" aria-label="Permalink to “Trapezoidal”">​</a></h2><div class="language-jule line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jule</span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#F286C4;">fn</span><span style="color:#F6F6F4;"> </span><span style="color:#97E1F1;">Trapezoidal</span><span style="color:#F6F6F4;">[T</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> integer </span><span style="color:#F286C4;">|</span><span style="color:#F6F6F4;"> float](x</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> []T, f</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> []T)</span><span style="color:#F286C4;">:</span><span style="color:#F6F6F4;"> T</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Returns an approximate value of the integral</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#f6f6f4;">\\int_a^b f(x) dx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>computed using the trapezoidal rule. The function f is given as a slice of samples evaluated at locations in x, that is,</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#f6f6f4;">f[i] = f(x[i]), x[0] = a, x[len(x)-1] = b</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The slice x must be sorted in strictly increasing order. x and f must be of equal length and the length must be at least 2.</p><p>The trapezoidal rule approximates f by a piecewise linear function and estimates</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#f6f6f4;">\\int_x[i]^x[i+1] f(x) dx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>as</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dracula-soft" style="background-color:#0000000;" tabindex="0"><code><span class="line"><span style="color:#f6f6f4;">(x[i+1] - x[i]) * (f[i] + f[i+1])/2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>More details on the trapezoidal rule can be found at: <a href="https://en" target="_blank" rel="noreferrer">https://en</a>.wikipedia.org/wiki/Trapezoidal_rule</p><p>Computations are performed using 64-bit floating-point precision. The result is returned as type T, which may cause rounding errors or loss of precision. To preserve exact results, use 64-bit floating-point type.</p></div>',3)]))}const f=e(o,[["render",r]]);export{b as __pageData,f as default};
